/*
 * 《凡人女修》红颜录 — slideshow wallpaper.
 *
 * Wallpaper Engine / LiteWall host contract:
 *   window.wallpaperPropertyListener.applyUserProperties(properties)
 *   window.wallpaperPropertyListener.applyGeneralProperties(properties)
 *   window.wallpaperPropertyListener.setPaused(isPaused)
 *
 * The frame list is loaded from manifest.js (generated by tools/build-slideshow.py).
 * No fetch/XHR is used: file:// origins reject them, so a plain <script> is the
 * only reliable local manifest carrier under WKWebView's read-access sandbox.
 */
(function () {
  'use strict';

  var images = Array.isArray(window.__FM_IMAGES) ? window.__FM_IMAGES.slice() : [];

  var config = {
    titletext: '凡人女修',
    interval: 12,
    fade: 1.6,
    accent: '0.78 0.26 0.22',
    kenburns: true,
    blurbackdrop: true,
    showtext: false,
    shuffle: false
  };

  var state = {
    paused: false,
    active: -1,
    cursor: 0,
    order: [],
    timer: null,
    enforceTimer: null,
    cache: Object.create(null),
    fps: 30
  };

  var layers = [
    {
      root: document.getElementById('slide-a'),
      back: document.getElementById('backdrop-a')
    },
    {
      root: document.getElementById('slide-b'),
      back: document.getElementById('backdrop-b')
    }
  ];
  layers[0].img = layers[0].root.querySelector('img');
  layers[1].img = layers[1].root.querySelector('img');

  var nameNode = document.getElementById('name');
  var counterNode = document.getElementById('counter');
  var brandTitle = document.getElementById('brand-title');
  var progressFill = document.getElementById('progress-fill');

  function clamp(value, low, high) {
    return Math.max(low, Math.min(high, value));
  }

  function pad(value) {
    return value < 10 ? '0' + value : String(value);
  }

  function parseColor(value) {
    var parts = String(value).trim().split(/\s+/).map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return null;
    return 'rgb(' + parts.map(function (c) {
      return Math.round(clamp(c, 0, 1) * 255);
    }).join(',') + ')';
  }

  function applyAccent(value) {
    var css = parseColor(value);
    if (css) document.documentElement.style.setProperty('--accent', css);
  }

  function rebuildOrder() {
    state.order = images.map(function (_, i) { return i; });
    if (config.shuffle) {
      for (var i = state.order.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = state.order[i];
        state.order[i] = state.order[j];
        state.order[j] = tmp;
      }
    }
    state.cursor = 0;
  }

  function nextStep() {
    if (!state.order.length || state.cursor >= state.order.length) rebuildOrder();
    var index = state.order[state.cursor++];
    return { entry: images[index], position: state.cursor, total: images.length };
  }

  function preload(file, done) {
    if (state.cache[file]) { done(true); return; }
    var probe = new Image();
    probe.onload = function () { state.cache[file] = true; done(true); };
    probe.onerror = function () { done(false); };
    probe.src = file;
  }

  function restartAnimation(node, value) {
    node.style.animation = 'none';
    void node.offsetWidth;               // force reflow so the animation restarts
    node.style.animation = value;
  }

  function present(step) {
    var outgoing = state.active;
    var next = outgoing < 0 ? 0 : 1 - outgoing;
    var layer = layers[next];
    var file = step.entry.file;

    // Clear the previous enforcement values so CSS transitions can animate.
    // This matters when the window is throttled (occluded desktop layer,
    // full-screen app, low-power mode): WebKit may freeze the compositor clock,
    // leaving opacity at its transition start value. A JS timer still fires and
    // pins the terminal values, so the wallpaper can never stay blank.
    layers.forEach(function (item) {
      item.root.style.opacity = '';
      item.back.style.opacity = '';
    });
    nameNode.style.opacity = '';

    layer.img.src = file;
    layer.back.style.backgroundImage = 'url("' + file + '")';

    layer.root.classList.remove('kb', 'on');
    void layer.root.offsetWidth;
    if (config.kenburns) layer.root.classList.add('kb');
    layer.root.classList.add('on');
    layer.back.classList.add('on');

    if (outgoing >= 0) {
      layers[outgoing].root.classList.remove('on');
      layers[outgoing].back.classList.remove('on');
    }
    state.active = next;

    nameNode.textContent = step.entry.name;
    restartAnimation(nameNode, 'rise 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both');
    counterNode.textContent = pad(step.position) + ' / ' + pad(step.total);

    clearTimeout(state.enforceTimer);
    state.enforceTimer = setTimeout(function () {
      layer.root.style.opacity = '1';
      layer.back.style.opacity = '1';
      if (outgoing >= 0) {
        layers[outgoing].root.style.opacity = '0';
        layers[outgoing].back.style.opacity = '0';
      }
      nameNode.style.opacity = '1';
    }, config.fade * 1000 + 180);
  }

  function resetProgress(seconds) {
    progressFill.style.animation = 'none';
    void progressFill.offsetWidth;
    progressFill.style.animation = 'progress ' + seconds + 's linear forwards';
  }

  function schedule(overrideSeconds) {
    clearTimeout(state.timer);
    if (state.paused || !images.length) return;
    var seconds = overrideSeconds != null ? overrideSeconds : config.interval;
    resetProgress(seconds);
    state.timer = setTimeout(advance, seconds * 1000);
  }

  function advance() {
    var step = nextStep();
    if (!step) return;
    preload(step.entry.file, function (ok) {
      // A missing/undecodable frame is skipped rather than showing a blank screen.
      if (!ok) { schedule(0.4); return; }
      present(step);
      schedule();
    });
  }

  function start() {
    if (!images.length) {
      nameNode.textContent = '未找到图片 · 请运行 tools/build-slideshow.py';
      counterNode.textContent = '— / —';
      return;
    }
    rebuildOrder();
    advance();
  }

  // --- Wallpaper Engine host contract -------------------------------------

  // Must be a global assigned outside any event handler: the host delivers the
  // initial property snapshot in a microtask after this script finishes.
  window.wallpaperPropertyListener = {
    applyUserProperties: function (properties) {
      if (!properties) return;

      if (properties.titletext) {
        config.titletext = String(properties.titletext.value);
        brandTitle.textContent = config.titletext;
      }
      if (properties.interval) {
        config.interval = clamp(Number(properties.interval.value) || 12, 4, 60);
        schedule();
      }
      if (properties.fade) {
        config.fade = clamp(Number(properties.fade.value) || 1.6, 0.3, 5);
        document.documentElement.style.setProperty('--fade', config.fade + 's');
      }
      if (properties.accent) {
        config.accent = String(properties.accent.value);
        applyAccent(config.accent);
      }
      if (properties.kenburns) {
        config.kenburns = Boolean(properties.kenburns.value);
        layers.forEach(function (layer) {
          layer.root.classList.toggle('kb', config.kenburns);
        });
      }
      if (properties.blurbackdrop) {
        document.body.classList.toggle('no-blur', !Boolean(properties.blurbackdrop.value));
      }
      if (properties.showtext) {
        config.showtext = Boolean(properties.showtext.value);
        document.body.classList.toggle('no-text', !config.showtext);
      }
      if (properties.shuffle) {
        config.shuffle = Boolean(properties.shuffle.value);
        rebuildOrder();
      }
    },

    applyGeneralProperties: function (properties) {
      // Recorded for parity with the host's FPS setting. CSS-driven motion is
      // compositor-managed, so no JS frame loop needs throttling here.
      if (properties && properties.fps) {
        state.fps = clamp(Number(properties.fps) || 30, 1, 120);
      }
    },

    setPaused: function (isPaused) {
      state.paused = Boolean(isPaused);
      document.body.classList.toggle('paused', state.paused);
      if (state.paused) clearTimeout(state.timer);
      else schedule();
    }
  };

  // --- defaults before the host snapshot arrives ---------------------------
  document.documentElement.style.setProperty('--fade', config.fade + 's');
  document.body.classList.toggle('no-text', !config.showtext);
  applyAccent(config.accent);
  brandTitle.textContent = config.titletext;
  start();
})();
